// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.NotifyingSailConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Value-dictionary garbage collection must not reclaim IDs that a pinned SNAPSHOT reader can still resolve: a writer at
 * isolation NONE removes statements and commits straight into LMDB while the reader is open, and the removed values'
 * IDs must stay resolvable for the reader's whole transaction.
 */
public class LmdbSnapshotValueGcTest {

	@TempDir
	File dataDir;

	@Test
	public void pinnedReaderResolvesValuesRemovedAfterItsSnapshot() throws Exception {
		LmdbStore store = new LmdbStore(new File(dataDir, "store"), new LmdbStoreConfig("spoc,posc"));
		store.init();
		try {
			ValueFactory vf = SimpleValueFactory.getInstance();
			IRI pred = vf.createIRI("http://example.com/p");
			try (NotifyingSailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(vf.createIRI("http://example.com/doomed"), pred,
						vf.createLiteral("doomed-value"));
				for (int i = 0; i < 5; i++) {
					connection.addStatement(vf.createIRI("http://example.com/s" + i), pred,
							vf.createLiteral("value-" + i));
				}
				connection.commit();
			}

			try (NotifyingSailConnection reader = store.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				List<String> before = readObjects(reader, vf.createIRI("http://example.com/doomed"),
						vf.createIRI("http://example.com/p"));
				assertThat(before).containsExactly("doomed-value");

				try (NotifyingSailConnection writer = store.getConnection()) {
					writer.begin(IsolationLevels.NONE);
					writer.removeStatements(vf.createIRI("http://example.com/doomed"),
							vf.createIRI("http://example.com/p"), null);
					writer.commit();
				}

				// fresh Value instances force full value→ID resolution through the dictionary
				List<String> after = readObjects(reader, vf.createIRI("http://example.com/doomed"),
						vf.createIRI("http://example.com/p"));
				assertThat(after)
						.as("pinned SNAPSHOT reader must still resolve values removed after its snapshot")
						.containsExactly("doomed-value");
				reader.commit();
			}

			try (NotifyingSailConnection fresh = store.getConnection()) {
				fresh.begin(IsolationLevels.SNAPSHOT);
				assertThat(readObjects(fresh, vf.createIRI("http://example.com/doomed"),
						vf.createIRI("http://example.com/p"))).isEmpty();
				fresh.commit();
			}
		} finally {
			store.shutDown();
		}
	}

	private static List<String> readObjects(NotifyingSailConnection connection, IRI subject, IRI predicate) {
		try (CloseableIteration<? extends Statement> statements = connection.getStatements(subject, predicate, null,
				false)) {
			return statements.stream().map(st -> st.getObject().stringValue()).sorted().collect(Collectors.toList());
		}
	}
}
